<?php
declare(strict_types=1);
require_once __DIR__ . '/../app/bootstrap.php';
use BAJAMA\Core\Auth; use BAJAMA\Core\License; use BAJAMA\Core\RBAC; use BAJAMA\Core\Tenant;
Auth::requireLogin();$db=db();License::requireFeature($db,'mikrotik');RBAC::require($db,'network.view');$organizationId=Tenant::id();$canManage=RBAC::hasPermission($db,'network.manage');$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf((string)($_POST['_csrf']??$_POST['csrf']??''));if(!$canManage)throw new RuntimeException('Akses ditolak.');$action=(string)($_POST['action']??'');$id=(int)($_POST['id']??0);if($action==='delete'||$action==='toggle'){$sql=$action==='delete'?'DELETE FROM network_ftth_services WHERE id=? AND organization_id=?':'UPDATE network_ftth_services SET enabled=CASE WHEN enabled=1 THEN 0 ELSE 1 END WHERE id=? AND organization_id=?';$db->prepare($sql)->execute([$id,$organizationId]);$message=$action==='delete'?'Layanan FTTH dihapus.':'Status FTTH diubah.';}if($action==='save'){$routerId=(int)($_POST['router_id']??0);$oltId=(int)($_POST['olt_id']??0);$customerId=(int)($_POST['customer_id']??0);$subscriptionId=(int)($_POST['subscription_id']??0);$pon=trim((string)($_POST['pon_port']??''));$serial=strtoupper(trim((string)($_POST['onu_serial']??'')));$onu=trim((string)($_POST['onu_type']??''));$status=strtoupper((string)($_POST['status']??'PLANNED'));$notes=trim((string)($_POST['notes']??''));if(!$routerId||!$oltId||$pon===''||$serial===''||!in_array($status,['PLANNED','PROVISIONING','ONLINE','OFFLINE','SUSPENDED','DECOMMISSIONED'],true))throw new RuntimeException('Router, OLT, PON, ONU serial, dan status wajib valid.');$q=$db->prepare('SELECT id FROM network_olts WHERE id=? AND router_id=? AND organization_id=? AND enabled=1');$q->execute([$oltId,$routerId,$organizationId]);if(!$q->fetchColumn())throw new RuntimeException('OLT tidak aktif atau tidak terhubung ke router.');$values=[$routerId,$oltId,$customerId?:null,$subscriptionId?:null,$pon,$serial,$onu?:null,$status,$notes?:null];if($id)$db->prepare('UPDATE network_ftth_services SET router_id=?,olt_id=?,customer_id=?,subscription_id=?,pon_port=?,onu_serial=?,onu_type=?,status=?,notes=? WHERE id=? AND organization_id=?')->execute([...$values,$id,$organizationId]);else$db->prepare('INSERT INTO network_ftth_services (organization_id,router_id,olt_id,customer_id,subscription_id,pon_port,onu_serial,onu_type,status,notes) VALUES (?,?,?,?,?,?,?,?,?,?)')->execute([$organizationId,...$values]);$message='FTTH berhasil disimpan.';}}catch(Throwable $e){$error=$e->getMessage();}}
$editId=(int)($_GET['edit']??0);$edit=null;if($editId){$q=$db->prepare('SELECT * FROM network_ftth_services WHERE id=? AND organization_id=?');$q->execute([$editId,$organizationId]);$edit=$q->fetch(PDO::FETCH_ASSOC)?:null;}$q=$db->prepare('SELECT id,name,host FROM mikrotik_routers WHERE organization_id=? ORDER BY name');$q->execute([$organizationId]);$routers=$q->fetchAll(PDO::FETCH_ASSOC);$q=$db->prepare('SELECT id,name,router_id,vendor FROM network_olts WHERE organization_id=? AND enabled=1 ORDER BY name');$q->execute([$organizationId]);$olts=$q->fetchAll(PDO::FETCH_ASSOC);$q=$db->prepare('SELECT id,customer_code,name FROM customers WHERE organization_id=? ORDER BY name');$q->execute([$organizationId]);$customers=$q->fetchAll(PDO::FETCH_ASSOC);$q=$db->prepare('SELECT id,service_name,username FROM subscriptions WHERE organization_id=? ORDER BY service_name');$q->execute([$organizationId]);$subscriptions=$q->fetchAll(PDO::FETCH_ASSOC);$q=$db->prepare('SELECT f.*,o.name olt_name,r.name router_name,c.name customer_name FROM network_ftth_services f JOIN network_olts o ON o.id=f.olt_id AND o.organization_id=f.organization_id JOIN mikrotik_routers r ON r.id=f.router_id AND r.organization_id=f.organization_id LEFT JOIN customers c ON c.id=f.customer_id AND c.organization_id=f.organization_id WHERE f.organization_id=? ORDER BY f.id DESC');$q->execute([$organizationId]);$items=$q->fetchAll(PDO::FETCH_ASSOC);function ft_h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}$pageTitle='FTTH Services';ob_start();
?>
<div class="container-fluid py-4"><h1>FTTH Services</h1><p class="text-muted">Pilih router MikroTik dan OLT aktif. PON port serta ONU serial menjadi identitas fiber.</p><?php if($message):?><div class="alert alert-success"><?=ft_h($message)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=ft_h($error)?></div><?php endif;?><div class="card mb-4"><div class="card-body"><h2 class="h5"><?= $edit?'Edit':'Tambah' ?> FTTH</h2><form method="post" class="row g-3"><input type="hidden" name="_csrf" value="<?=ft_h(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><div class="col-md-3"><label class="form-label">Router</label><select class="form-select" name="router_id" required><option value="">Pilih router</option><?php foreach($routers as $v):?><option value="<?=$v['id']?>" <?=((int)($edit['router_id']??0)==$v['id']?'selected':'')?>><?=ft_h($v['name'].' - '.$v['host'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">OLT Aktif</label><select class="form-select" name="olt_id" required><option value="">Pilih OLT</option><?php foreach($olts as $v):?><option value="<?=$v['id']?>" data-router="<?=$v['router_id']?>" <?=((int)($edit['olt_id']??0)==$v['id']?'selected':'')?>><?=ft_h($v['name'].' / '.$v['vendor'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">PON Port</label><input class="form-control" name="pon_port" value="<?=ft_h($edit['pon_port']??'')?>" required></div><div class="col-md-2"><label class="form-label">ONU Serial</label><input class="form-control" name="onu_serial" value="<?=ft_h($edit['onu_serial']??'')?>" required></div><div class="col-md-2"><label class="form-label">ONU Type</label><input class="form-control" name="onu_type" value="<?=ft_h($edit['onu_type']??'')?>"></div><div class="col-md-3"><label class="form-label">Customer</label><select class="form-select" name="customer_id"><option value="0">Tanpa customer</option><?php foreach($customers as $v):?><option value="<?=$v['id']?>" <?=((int)($edit['customer_id']??0)==$v['id']?'selected':'')?>><?=ft_h($v['customer_code'].' - '.$v['name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Subscription</label><select class="form-select" name="subscription_id"><option value="0">Tanpa subscription</option><?php foreach($subscriptions as $v):?><option value="<?=$v['id']?>" <?=((int)($edit['subscription_id']??0)==$v['id']?'selected':'')?>><?=ft_h($v['service_name'].' '.$v['username'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['PLANNED','PROVISIONING','ONLINE','OFFLINE','SUSPENDED','DECOMMISSIONED'] as $v):?><option <?=$v===($edit['status']??'PLANNED')?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Catatan</label><input class="form-control" name="notes" value="<?=ft_h($edit['notes']??'')?>"></div><div class="col-12"><button class="btn btn-primary">Simpan</button></div></form></div></div><div class="card"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Customer</th><th>Router</th><th>OLT/PON</th><th>ONU</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=ft_h($i['customer_name']??'-')?></td><td><?=ft_h($i['router_name'])?></td><td><?=ft_h($i['olt_name'])?> / <?=ft_h($i['pon_port'])?></td><td><code><?=ft_h($i['onu_serial'])?></code></td><td><?=$i['enabled']?'ENABLED':'DISABLED'?> / <?=ft_h($i['status'])?></td><td><a class="btn btn-sm btn-outline-primary" href="network_ftth.php?edit=<?=$i['id']?>">Edit</a><form class="d-inline" method="post"><input type="hidden" name="_csrf" value="<?=ft_h(csrf_token())?>"><input type="hidden" name="id" value="<?=$i['id']?>"><button name="action" value="toggle" class="btn btn-sm btn-outline-warning">Enable/Disable</button><button name="action" value="delete" class="btn btn-sm btn-outline-danger">Hapus</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div><script>document.querySelector('select[name="router_id"]')?.addEventListener('change',function(){document.querySelectorAll('select[name="olt_id"] option[data-router]').forEach(function(option){option.hidden=option.dataset.router!==this.value;},this);});</script><?php $content=ob_get_clean();require __DIR__.'/../app/layout/layout.php';
